window.KH_SURA(44, {"sura": "الدخان", "n": 44, "ayat": {"1": "حم", "2": "وَالْكِتَابِ الْمُبِينِ", "3": "إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةٍ مُبَارَكَةٍ إِنَّا كُنَّا مُنْذِرِينَ", "4": "فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ", "5": "أَمْرًا مِنْ عِنْدِنَا إِنَّا كُنَّا مُرْسِلِينَ", "6": "رَحْمَةً مِنْ رَبِّكَ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ", "7": "رَبِّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِنْ كُنْتُمْ مُوقِنِينَ", "8": "لَا إِلَهَ إِلَّا هُوَ يُحْيِي وَيُمِيتُ رَبُّكُمْ وَرَبُّ آبَائِكُمُ الْأَوَّلِينَ", "9": "بَلْ هُمْ فِي شَكٍّ يَلْعَبُونَ", "10": "فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ", "11": "يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ", "12": "رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ", "13": "أَنَّى لَهُمُ الذِّكْرَى وَقَدْ جَاءَهُمْ رَسُولٌ مُبِينٌ", "14": "ثُمَّ تَوَلَّوْا عَنْهُ وَقَالُوا مُعَلَّمٌ مَجْنُونٌ", "15": "إِنَّا كَاشِفُو الْعَذَابِ قَلِيلًا إِنَّكُمْ عَائِدُونَ", "16": "يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ", "17": "وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَاءَهُمْ رَسُولٌ كَرِيمٌ", "18": "أَنْ أَدُّوا إِلَيَّ عِبَادَ اللَّهِ إِنِّي لَكُمْ رَسُولٌ أَمِينٌ", "19": "وَأَنْ لَا تَعْلُوا عَلَى اللَّهِ إِنِّي آتِيكُمْ بِسُلْطَانٍ مُبِينٍ", "20": "وَإِنِّي عُذْتُ بِرَبِّي وَرَبِّكُمْ أَنْ تَرْجُمُونِ", "21": "وَإِنْ لَمْ تُؤْمِنُوا لِي فَاعْتَزِلُونِ", "22": "فَدَعَا رَبَّهُ أَنَّ هَؤُلَاءِ قَوْمٌ مُجْرِمُونَ", "23": "فَأَسْرِ بِعِبَادِي لَيْلًا إِنَّكُمْ مُتَّبَعُونَ", "24": "وَاتْرُكِ الْبَحْرَ رَهْوًا إِنَّهُمْ جُنْدٌ مُغْرَقُونَ", "25": "كَمْ تَرَكُوا مِنْ جَنَّاتٍ وَعُيُونٍ", "26": "وَزُرُوعٍ وَمَقَامٍ كَرِيمٍ", "27": "وَنَعْمَةٍ كَانُوا فِيهَا فَاكِهِينَ", "28": "كَذَلِكَ وَأَوْرَثْنَاهَا قَوْمًا آخَرِينَ", "29": "فَمَا بَكَتْ عَلَيْهِمُ السَّمَاءُ وَالْأَرْضُ وَمَا كَانُوا مُنْظَرِينَ", "30": "وَلَقَدْ نَجَّيْنَا بَنِي إِسْرَائِيلَ مِنَ الْعَذَابِ الْمُهِينِ", "31": "مِنْ فِرْعَوْنَ إِنَّهُ كَانَ عَالِيًا مِنَ الْمُسْرِفِينَ", "32": "وَلَقَدِ اخْتَرْنَاهُمْ عَلَى عِلْمٍ عَلَى الْعَالَمِينَ", "33": "وَآتَيْنَاهُمْ مِنَ الْآيَاتِ مَا فِيهِ بَلَاءٌ مُبِينٌ", "34": "إِنَّ هَؤُلَاءِ لَيَقُولُونَ", "35": "إِنْ هِيَ إِلَّا مَوْتَتُنَا الْأُولَى وَمَا نَحْنُ بِمُنْشَرِينَ", "36": "فَأْتُوا بِآبَائِنَا إِنْ كُنْتُمْ صَادِقِينَ", "37": "أَهُمْ خَيْرٌ أَمْ قَوْمُ تُبَّعٍ وَالَّذِينَ مِنْ قَبْلِهِمْ أَهْلَكْنَاهُمْ إِنَّهُمْ كَانُوا مُجْرِمِينَ", "38": "وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا لَاعِبِينَ", "39": "مَا خَلَقْنَاهُمَا إِلَّا بِالْحَقِّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ", "40": "إِنَّ يَوْمَ الْفَصْلِ مِيقَاتُهُمْ أَجْمَعِينَ", "41": "يَوْمَ لَا يُغْنِي مَوْلًى عَنْ مَوْلًى شَيْئًا وَلَا هُمْ يُنْصَرُونَ", "42": "إِلَّا مَنْ رَحِمَ اللَّهُ إِنَّهُ هُوَ الْعَزِيزُ الرَّحِيمُ", "43": "إِنَّ شَجَرَتَ الزَّقُّومِ", "44": "طَعَامُ الْأَثِيمِ", "45": "كَالْمُهْلِ يَغْلِي فِي الْبُطُونِ", "46": "كَغَلْيِ الْحَمِيمِ", "47": "خُذُوهُ فَاعْتِلُوهُ إِلَى سَوَاءِ الْجَحِيمِ", "48": "ثُمَّ صُبُّوا فَوْقَ رَأْسِهِ مِنْ عَذَابِ الْحَمِيمِ", "49": "ذُقْ إِنَّكَ أَنْتَ الْعَزِيزُ الْكَرِيمُ", "50": "إِنَّ هَذَا مَا كُنْتُمْ بِهِ تَمْتَرُونَ", "51": "إِنَّ الْمُتَّقِينَ فِي مَقَامٍ أَمِينٍ", "52": "فِي جَنَّاتٍ وَعُيُونٍ", "53": "يَلْبَسُونَ مِنْ سُنْدُسٍ وَإِسْتَبْرَقٍ مُتَقَابِلِينَ", "54": "كَذَلِكَ وَزَوَّجْنَاهُمْ بِحُورٍ عِينٍ", "55": "يَدْعُونَ فِيهَا بِكُلِّ فَاكِهَةٍ آمِنِينَ", "56": "لَا يَذُوقُونَ فِيهَا الْمَوْتَ إِلَّا الْمَوْتَةَ الْأُولَى وَوَقَاهُمْ عَذَابَ الْجَحِيمِ", "57": "فَضْلًا مِنْ رَبِّكَ ذَلِكَ هُوَ الْفَوْزُ الْعَظِيمُ", "58": "فَإِنَّمَا يَسَّرْنَاهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ", "59": "فَارْتَقِبْ إِنَّهُمْ مُرْتَقِبُونَ"}, "units": [{"aya": 0, "title": "معنى", "mawsua": {"taliq": 5900, "masala": "معنى", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون من الفعل المتعدي؛ أي: يبين الهدى والشرع ونحوه", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون من غير المتعدي؛ أي: هو مبين في نفسه", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5900, "mi": 1, "aya": 0, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 569", "qawl": "", "nass": "{المبين} يحتمل أن يكون من الفعل المتعدي؛ أي: يبين الهدى والشرع ونحوه، ويحتمل أن يكون من غير المتعدي؛ أي: هو مبين في نفسه", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 3, "title": "سبب نزول: ﴿إنا أنزلناه في ليلة مباركة﴾", "tabari": {"page": "21/6", "sarih": 0, "tarjih": "والصواب من القول في ذلك قول من قال: عنى بها ليلة القدر. لأن الله أخبر تعالى ذكره أن ذلك كذلك بقوله : [﴿إنا أنزلناه في ليلة القدر﴾ [القدر: ١].", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "﴿إنا أنزلناه في ليلة مباركة﴾. أقسم ربنا جل ثناؤه بهذا الكتاب أنه أنزله في ليلة مباركة.", "taqdim": 1, "n_athar": 3, "qailun": [["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [69871, 69872, 69875]}, {"n": 2, "t": "بل هي ليلة النصف من شعبان", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5901, "mi": 1, "aya": 4, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 6 - 10", "qawl": "الأول", "nass": "", "qawaid": ["القرآن والنظائر"], "tabi": ""}, {"taliq": 5901, "mi": 1, "aya": 4, "alam": "ابن القيم", "fil": "رجح", "kind": "ترجيح", "ref": "2/ 440", "qawl": "الأول", "nass": "", "qawaid": ["القرآن والنظائر"], "tabi": "ابن جرير"}, {"taliq": 5901, "mi": 1, "aya": 4, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "ومن قال: إنها ليلة النصف من شعبان -كما روي عن عكرمة- فقد أبعد النجعة، فإن نص القرآن أنها في رمضان", "qawaid": [], "tabi": ""}], "mawsua": {"taliq": 5901, "masala": "تعيين الليلة المباركة التي يفرق فيها كل أمر حكيم", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها ليلة القدر", "ashab": "جمهور المفسرين", "athar": []}, {"n": 2, "t": "أنها ليلة النصف من شعبان", "ashab": "عكرمة", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن القيم", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["القرآن والنظائر"], "ابن القيم": ["القرآن والنظائر"]}, "rulesD": {}}}, {"aya": 4, "title": "في هذه الليلة التي يفرق فيها كل أمر حكيم نحو اختلافهم في الليلة المباركة، وذلك أن الهاء التي في قوله: ﴿فيها﴾. عائدة على الليلة المباركة", "tabari": {"page": "21/6", "sarih": 1, "tarjih": "وأولى القولين في ذلك بالصواب قول من قال: ذلك ليلة القدر. لما قد تقدم من بياننا عن أن المعني بقوله: ﴿إنا أنزلناه في ليلة مباركة﴾. ليلة القدر. والهاء في قوله: ﴿فيها﴾ من ذكر الليلة المباركة.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "هي ليلة القدر، يقضى فيها أمر السنة كلها؛ من يموت، ومن يولد، ومن يعز، ومن يذل، وسائر أمور السنة", "taqdim": 0, "n_athar": 10, "qailun": [["له رجل", ""], ["رجل للحسن وأنا أسمع", ""], ["أبي مالك", "تابعي"], ["هلال بن يساف", "تابعي"], ["أبي عبد الرحمن", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["منصور", ""]], "athar": [69882, 69884, 69885, 69889, 69890, 69894]}, {"n": 2, "t": "بل هي ليلة النصف من شعبان", "taqdim": 0, "n_athar": 3, "qailun": [["عكرمة", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [69878, 69879, 69880]}]}, "mawaqif": [], "mushid": {"i": 1, "imgs": ["044_001_1.png"], "pages": [465], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 5, "title": "قوله تعالى", "mawsua": {"taliq": 5902, "masala": "قوله تعالى", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن المراد: «إرسال الرسل والأنبياء", "ashab": "", "athar": []}, {"n": 2, "t": "أن المراد: «الرحمة» التي ذكرت بعد ذلك", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5902, "mi": 1, "aya": 5, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 570", "qawl": "", "nass": "إرسال الرسل والأنبياء", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 10, "title": "في هذا اليوم الذي أمر الله نبيه محمدا ﷺ أن يرتقبه، وأخبره أن السماء تأتى فيه بدخان مبين", "tabari": {"page": "21/13", "sarih": 1, "tarjih": "وأولى القولين بالصواب في ذلك ما روى عن ابن مسعود، من أن الدخان الذي أمر الله نبيه ﷺ أن يرتقبه، هو ما أصاب قومه من الجهد بدعائه عليهم، على ما وصفه ابن مسعود من ذلك، إن لم يكن خبر حذيفة الذي ذكرناه عنه عن رسول الله ﷺ صحيحا، وإن كان صحيحا، فرسول الله ﷺ أعلم بما أنزل الله عليه، وليس لأحد مع قوله الذي يصح عنه قول.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "ذلك حين دعا رسول الله على قريش ربه أن يأخذهم بسنين كسنى يوسف، فأخذوا بالمجاعة. قالوا: وعنى بالدخان ما كان يصيبهم حينئذ في أبصارهم من شدة الجوع؛ من الظلمة كهيئة الدخان", "taqdim": 0, "n_athar": 13, "qailun": [["مسروق", "تابعي"], ["عاصم", "تابعي"], ["ابن مسعود", "صحابي"], ["إبراهيم", "تابعي"], ["محمد", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["عبد الله", "صحابي"]], "athar": [69903, 69906, 69907, 69908, 69909, 69910, 69911, 69912, 69913, 69914, 69915, 69918, 69920, 69923, 69924]}, {"n": 2, "t": "الدخان آية من آيات الله، مرسلة على عباده قبل مجيء الساعة، فيدخل في أسماع أهل الكفر به، ويعترى أهل الإيمان به كهيئة الزكام. قالوا: ولم يأت بعد، وهو آت", "taqdim": 0, "n_athar": 7, "qailun": [["ابن عمر", "صحابي"], ["عوف", ""], ["أبي سعيد", "صحابي"], ["حذيفة", "صحابي"], ["أبي مالك الأشعري", "صحابي"]], "athar": [69905, 69920, 69921, 69929, 69930]}]}, "mawaqif": [{"taliq": 5904, "mi": 1, "aya": 10, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 20", "qawl": "الأول", "nass": "لأن الله -جل ثناؤه- توعد بالدخان مشركي قريش، وأن قوله لنبيه صلى الله عليه وسلم: {فارتقب يوم تأتي السماء بدخان مبين} في سياق خطاب الله كفار قريش، وتقريعه إياهم بشركهم بقوله: {لا إله إلا هو يحيي ويميت ربكم ورب آبائكم الأولين بل هم في شك يلعبون}، ثم أتبع ذلك قوله لنبيه عليه الصلاة والسلام: {فارتقب يوم تأتي السماء بدخان مبين} أمرا منه له بالصبر إلى أن يأتيهم بأسه وتهديدا للمشركين، فهو بأن يكون إذ كان وعيدا لهم قد أحله بهم أشبه من أن يكون أخره عنهم لغيرهم", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 5904, "mi": 1, "aya": 10, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 571", "qawl": "الأول", "nass": "وما يأتي من الآيات يقوي هذا التأويل", "qawaid": [], "tabi": ""}, {"taliq": 5904, "mi": 1, "aya": 10, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 339", "qawl": "الثاني", "nass": "وهذا إسناد صحيح إلى ابن عباس، وهكذا قول من وافقه من الصحابة والتابعين أجمعين، مع الأحاديث المرفوعة من الصحاح والحسان وغيرهما، التي أوردناها مما فيه مقنع ودلالة ظاهرة على أن الدخان من الآيات المنتظرة، مع أنه ظاهر القرآن، قال الله تعالى: {فارتقب يوم تأتي السماء بدخان مبين} أي: بين واضح يراه كل أحد. وعلى ما فسر به ابن مسعود?: إنما هو خيال رأوه في أعينهم من شدة الجوع والجهد. وهكذا قوله: {يغشى الناس} أي: يتغشاهم ويعمهم، ولو كان أمرا خياليا يخص أهل مكة المشركين لما قيل فيه: {يغشى الناس}", "qawaid": ["ظاهر الآية ولفظها", "السنة", "الدلالة العقلية"], "tabi": ""}, {"taliq": 5904, "mi": 1, "aya": 10, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "12/ 337", "qawl": "", "nass": "وقد أجاد ابن جرير في هذا الحديث هاهنا، فإنه موضوع بهذا السند، وقد أكثر ابن جرير من سياقه في أماكن من هذا التفسير، وفيه منكرات كثيرة جدا، ولا سيما في أول سورة بني إسرائيل في ذكر المسجد الأقصى", "qawaid": [], "tabi": ""}, {"taliq": 5904, "mi": 1, "aya": 10, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "", "qawl": "", "nass": "وبعد، فإنه غير منكر أن يكون أحل بالكفار الذين توعدهم بهذا الوعيد ما توعدهم، ويكون محلا فيما يستأنف بعد بآخرين دخانا على ما جاءت به الأخبار عن رسول الله صلى الله عليه وسلم عندنا كذلك؛ لأن الأخبار عن رسول الله صلى الله عليه وسلم قد تظاهرت بأن ذلك كائن، فإنه قد كان ما روى عنه عبد الله بن مسعود، فكلا الخبرين اللذين رويا عن رسول الله صلى الله عليه وسلم صحيح، وإن كان تأويل الآية في هذا الموضع ما قلنا", "qawaid": [], "tabi": ""}, {"taliq": 5904, "mi": 1, "aya": 10, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 572", "qawl": "", "nass": "ويحتمل إن صح حديث حذيفة أن يكون قد مر دخان، ويأتي دخان آخر", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["044_002_1.png"], "pages": [465], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5904, "masala": "وقت الدخان", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه الدخان الذي رأته قريش حين دعا عليهم رسول الله صلى الله عليه وسلم بسبع كسبع يوسف عليه السلام، فأصابهم جوع، فكانوا يرون بينهم وبين السماء كهيئة الدخان من الجوع", "ashab": "ابن مسعود، وأبي العالية، وإبراهيم النخعي، ومجاهد، والضحاك، ومقاتل", "athar": [69906, 69907, 69908, 69909, 69910, 69911, 69913, 69914, 69922, 69923, 69924, 69925, 69928]}, {"n": 2, "t": "دخان يجيء قبل القيامة فيأخذ بأنفاس الكفار، ويأخذ المؤمنين منه كهيئة الزكام", "ashab": "علي بن أبي طالب، وأبي سعيد الخدري، وابن عمر، وابن عباس، والحسن", "athar": [69916, 69921, 69930, 69920, 69918, 69926, 69931]}, {"n": 3, "t": "أنه كان يوم فتح مكة", "ashab": "أبي هريرة، والأعرج", "athar": [69917, 69927]}]}, "tags": {"m": {"1": [["ابن جرير", "r"]], "2": [["ابن كثير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق"], "ابن كثير": ["ظاهر الآية ولفظها", "السنة", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 11, "title": "قوله تعالى", "mawsua": {"taliq": 5905, "masala": "قوله تعالى", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون إخبارا من الله تعالى، كأنه يعجب منه على نحو من قوله تعالى لما وصف قصة الذبح: {إن هذا لهو البلاء المبين} [الصافات: 106]", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون {هذا عذاب أليم} من قول الناس، كأن تقدير الكلام، يقولون: هذا عذاب أليم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5905, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 572", "qawl": "", "nass": "وقوله تعالى: {هذا عذاب أليم} يحتمل أن يكون إخبارا من الله تعالى، كأنه يعجب منه على نحو من قوله تعالى لما وصف قصة الذبح: {إن هذا لهو البلاء المبين} [الصافات: 106]، ويحتمل أن يكون {هذا عذاب أليم} من قول الناس، كأن تقدير الكلام، يقولون: هذا عذاب أليم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 16, "title": "في البطشة الكبرى", "tabari": {"page": "21/25", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هي بطشة الله بمشركي قريش يوم بدر", "taqdim": 0, "n_athar": 12, "qailun": [["ابن مسعود", "صحابي"], ["مسروق", "تابعي"], ["محمد", "تابعي"], ["مجاهد", "تابعي"], ["ابن عباس", "صحابي"], ["إبراهيم", "تابعي"], ["أبي بن كعب", "صحابي"], ["ابن زيد", "تابع التابعين"]], "athar": [69946, 69947, 69948, 69950, 69952, 69953, 69957, 69960, 69963, 69968]}, {"n": 2, "t": "بل هي بطشة الله بأعدائه يوم القيامة", "taqdim": 0, "n_athar": 3, "qailun": [["عكرمة", "تابعي"], ["إبراهيم", "تابعي"], ["قتادة", "تابعي"]], "athar": [69950, 69959]}]}, "mawaqif": [], "mushid": {"i": 3, "imgs": ["044_003_1.png"], "pages": [465], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 18, "title": "الشيء المؤدى", "mawsua": {"taliq": 5909, "masala": "الشيء المؤدى", "sigha": "ذكر قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أنه طلب منهم أن يؤدوا إليه بني إسرائيل", "ashab": "", "athar": []}, {"n": 2, "t": "أن يؤدوا إليه الطاعة والإيمان والأعمال", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5909, "mi": 1, "aya": 18, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 573", "qawl": "", "nass": "والظاهر من شرع موسى عليه السلام أنه بعث إلى دعاء فرعون إلى الإيمان، وأن يرسل بني إسرائيل، فلما أبى أن يؤمن بقيت المكافحة في أن يرسل بني إسرائيل، وفي إرسالهم هو قوله: {أن أدوا إلي عباد الله} أي: بني إسرائيل، ويقوي ذلك قوله بعد: {وإن لم تؤمنوا لي فاعتزلون}، وهذا قريب نص في أنه إنما يطلب بني إسرائيل فقط، ويؤيد ذلك أيضا قوله تعالى: {فأسر بعبادي}، فيظهر أنه إياهم أراد موسى بقوله: {عباد الله}", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 20, "title": "في معنى الرجم الذي استعاذه موسى نبي الله ﵇ بربه منه", "tabari": {"page": "21/31", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب ما دل عليه ظاهر الكلام، وهو أن موسى ﵇ استعاذ بالله من أن يرجمه فرعون وقومه، والرجم قد يكون قولا باللسان، وفعلا باليد. والصواب أن يقال: استعاذ موسى بربه بربه من كل معاني رجمهم، الذي يصل منه إلى المرجوم أذى ومكروه؛ شتما كان ذلك باللسان، أو رجما بالحجارة باليد.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هو الشتم باللسان", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["أبي صالح", "تابعي"]], "athar": [69981, 69982, 69984, 69985]}, {"n": 2, "t": "بل هو الرجم بالحجارة", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"]], "athar": [69983]}, {"n": 3, "t": "بل عنى بقوله: ﴿أن ترجمون﴾: أن تقتلوني", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5911, "mi": 1, "aya": 20, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 32", "qawl": "", "nass": "وأولى الأقوال في ذلك بالصواب ما دل عليه ظاهر الكلام، وهو أن موسى عليه السلام استعاذ بالله من أن يرجمه فرعون وقومه، والرجم قد يكون قولا باللسان، وفعلا باليد، والصواب أن يقال: استعاذ موسى بربه من كل معاني رجمهم الذي يصل منه إلى المرجوم أذى ومكروه، شتما كان ذلك باللسان، أو رجما بالحجارة باليد", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 5911, "mi": 1, "aya": 20, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 574 بتصرف", "qawl": "الثاني", "nass": "قال قتادة وغيره: أراد الرجم بالحجارة المؤدي إلى القتل. وهو أظهر؛ لأنه أعيذ منه، ولم يعذ من الآخر، بل قيل فيه عليه السلام وله", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "mushid": {"i": 4, "imgs": ["044_004_1.png"], "pages": [466], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5911, "masala": "معنى الرجم", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه الشتم والسب", "ashab": "", "athar": []}, {"n": 2, "t": "أنه الرجم بالحجارة", "ashab": "", "athar": []}, {"n": 3, "t": "أنه القتل", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن عطية", "r"]]}, "t": {"2": [["ابن عطية", "r"]]}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["العموم"], "ابن عطية": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 24, "title": "في معنى الرهو", "tabari": {"page": "21/35", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب قول من قال: معناه: اتركه على هيئته كما هو، على الحال التي كان عليها حين سلكته. وذلك أن الرهو في كلام العرب السكون، كما قال الشاعر :", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: اتركه على هيئته وحاله التي كان عليها", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["قول الله", ""]], "athar": [69993, 69994, 69995, 69996, 69997, 69998]}, {"n": 2, "t": "بل معناه: اتركه سهلا", "taqdim": 0, "n_athar": 5, "qailun": [["الربيع", "تابعي"], ["ابن عباس", "صحابي"], ["الضحاك بن مزاحم", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [69993, 69994, 69995, 69996, 69997, 69998, 70002, 70011, 70013]}, {"n": 3, "t": "بل معناه: واتركه يبسا جددا", "taqdim": 0, "n_athar": 4, "qailun": [["عكرمة", "تابعي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [69999, 70000, 70001, 70008, 70009]}]}, "mawaqif": [{"taliq": 5913, "mi": 1, "aya": 24, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 37", "qawl": "الأول", "nass": "وأولى الأقوال في ذلك بالصواب قول من قال: معناه: اتركه على هيئته كما هو على الحال التي كان عليها حين سلكته، وذلك أن الرهو في كلام العرب: السكون … وإذ كان ذلك معناه كان لا شك أنه متروك سهلا دمثا، وطريقا يبسا؛ لأن بني إسرائيل قطعوه حين قطعوه وهو كذلك، فإذا ترك البحر رهوا كما كان حين قطعه موسى ساكنا لم يهج؛ كان لا شك أنه بالصفة التي وصفت", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 5913, "mi": 1, "aya": 24, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 575", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 5, "imgs": ["044_005_1.png"], "pages": [466], "n": 3, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5913, "masala": "معنى قوله: {رهوا}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "على هيئته وحاله التي كان عليها", "ashab": "", "athar": []}, {"n": 2, "t": "سهلا", "ashab": "", "athar": []}, {"n": 3, "t": "يبسا جددا", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن عطية", "r"]]}, "t": {"1": [["ابن جرير", "r"], ["ابن عطية", "r"]]}, "gen": [], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 26, "title": "في معنى وصف الله ذلك المقام بالكرم", "tabari": {"page": "21/38", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "وصفه بذلك لشرفه، وذلك أنه مقام الملوك والأمراء، قالوا: وإنما أريد به المنابر", "taqdim": 0, "n_athar": 2, "qailun": [["مجاهد", "تابعي"], ["سعيد بن جبير", "تابعي"]], "athar": [70017, 70018]}, {"n": 2, "t": "وصف ذلك المقام بالكرم؛ لحسنه وبهجته", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [70019]}]}, "mawaqif": [{"taliq": 5915, "mi": 1, "aya": 26, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 577", "qawl": "الأول", "nass": "والقول بالمنابر يهي جدا", "qawaid": [], "tabi": ""}], "mushid": {"i": 6, "imgs": ["044_006_1.png"], "pages": [466], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5915, "masala": "معنى المقام الكريم", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "المنابر", "ashab": "", "athar": []}, {"n": 2, "t": "المواضع الحسان", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن عطية", "d"]]}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 29, "title": "تأويل: ﴿فما بكت عليهم السماء والأرض وما كانوا منظرين ولقد نجينا بني إسرائيل من العذاب المهين من فر﴾", "tabari": {"page": "21/41", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: فما بكت على هؤلاء الذين غرقهم الله في البحر، وهم فرعون وقومه، السماء والأرض. وقيل: إن بكاء السماء حمرة أطرافها.", "taqdim": 1, "n_athar": 2, "qailun": [["السدي", "تابعي"], ["عطاء", "تابعي"]], "athar": [70043, 70057, 70058]}, {"n": 2, "t": "إنما قيل: ﴿فما بكت عليهم السماء والأرض﴾؛ لأن المؤمن إذا مات بكت عليه السماء والأرض أربعين صباحا، ولم يبكيا على فرعون وقومه؛ لأنه لم يكن لهم عمل يصعد إلى الله صالح فتبكي عليهم السماء ، ولا مسجد في الأرض فتبكي عليهم الأرض", "taqdim": 0, "n_athar": 13, "qailun": [["سعيد بن جبير", "تابعي"], ["مجاهد", "تابعي"], ["ابن عباس", "صحابي"], ["شريح بن عبيد الحضرمي", "تابعي"], ["قتادة", "تابعي"]], "athar": [70030, 70033, 70034, 70035, 70037, 70038, 70039, 70040, 70046, 70047, 70049, 70051, 70052, 70053, 70054]}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 32, "title": "قوله: {على علم}", "mawsua": {"taliq": 5920, "masala": "قوله: {على علم}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "معناه: على شيء سبق عندنا فيهم، ويكون قوله: {على العالمين} مرادا به جميع الناس. والمعنى: «لقد اخترناها لهذا الإنجاء وهذه النعم على سابق علم لنا فيهم، وخصصناهم بذلك دون العالم", "ashab": "", "athar": []}, {"n": 2, "t": "أن قوله: {على علم} معناه: على علم لهم وفضائل فيهم، فيكون قوله: {على العالمين} أي: على عالم زمانهم، والمعنى: «اخترناهم للنبوات والرسالات", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5920, "mi": 1, "aya": 32, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 580", "qawl": "", "nass": "لقد اخترناها لهذا الإنجاء وهذه النعم على سابق علم لنا فيهم، وخصصناهم بذلك دون العالم", "qawaid": [], "tabi": ""}, {"taliq": 5920, "mi": 1, "aya": 32, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "2/ 441", "qawl": "", "nass": "لا خلاف بين الناس أن المعنى: على علم منا بأنهم أهل الاختيار. فالجملة في موضع نصب على الحال، أي: اخترناهم عالمين بهم وبأحوالهم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 33, "title": "في ذلك البلاء", "tabari": {"page": "21/47", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله تعالى ذكره أخبر أنه آتى بنى إسرائيل من الآيات ما فيه ابتلاؤهم واختبارهم، وقد يكون الابتلاء والاختبار بالرخاء، ويكون بالشدة، ولم يضع لنا دليلا من خبر ولا عقل أنه عنى بعض ذلك دون بعض، وقد كان الله اختبرهم بالمعنيين كليهما جميعا، وجائز أن يكون عنى اختباره إياهم بهما. فإذ كان الأمر على ما وصفنا، فالصواب من القول فيه أن نقول كما قال جل ثناؤه: إنه اختبرهم.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "ابتلاهم بنعمه عندهم", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [70069]}, {"n": 2, "t": "بل ابتلاهم بالرخاء والشدة", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [70071]}]}, "mawaqif": [{"taliq": 5921, "mi": 1, "aya": 33, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 48", "qawl": "", "nass": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله أخبر أنه آتى بني إسرائيل من الآيات ما فيه ابتلاؤهم واختبارهم، وقد يكون الابتلاء والاختبار بالرخاء، ويكون بالشدة، ولم يضع لنا دليلا من خبر ولا عقل أنه عنى بعض ذلك دون بعض، وقد كان الله اختبرهم بالمعنيين كليهما جميعا. وجائز أن يكون عنى اختباره إياهم بهما، فإذا كان الأمر على ما وصفنا فالصواب من القول فيه أن نقول كما قال -جل ثناؤه-: إنه اختبرهم", "qawaid": [], "tabi": ""}], "mushid": {"i": 7, "imgs": ["044_007_1.png"], "pages": [466], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5921, "masala": "البلاء المذكور في قوله: {وآتيناهم من الآيات ما فيه بلاء مبين}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه ابتلاهم بنعمه عليهم من فلق البحر وإنجائهم من عدوهم وغير ذلك", "ashab": "", "athar": []}, {"n": 2, "t": "أنه ابتلاهم بالشدة والرخاء", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {}, "rulesD": {}}}, {"aya": 37, "title": "تأويل: ﴿إنهم كانوا مجرمين﴾", "tabari": {"page": "21/50", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿إنهم كانوا مجرمين﴾. يقول: إن قوم تبع والذين من قبلهم من الأمم الذين أهلكناهم؛ إنما أهلكناهم لإجرامهم، وكفرهم بربهم.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿إنهم كانوا مجرمين﴾. فكسرت ألف \"إن\" على وجه الابتداء وفيها معنى الشرط، استغناء بدلالة الكلام على معناها", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 42, "title": "في موضع ﴿من﴾ في قوله: ﴿إلا من رحم الله﴾", "tabari": {"page": "21/52", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب أن يكون في موضع رفع، بمعنى: يوم لا يغنى مولى عن مولى شيئا إلا من رحم الله منهم، فإنه يغنى عنه، بأن يشفع له عند ربه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "﴿إلا من رحم الله﴾. فجعله بدلا من الاسم المضمر في: ﴿ينصرون﴾. وإن شئت جعلته مبتدأ، وأضمرت خبره، تريد به: إلا من رحم الله فيغنى عنه", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿إلا من رحم الله﴾. قال: المؤمنون يشفع بعضهم في بعض، فإن شئت فاجعل ﴿من﴾ في موضع رفع، كأنك قلت:", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "معناه: لا يغنى مولى عن مولى شيئا، إلا من أذن الله له أن يشفع. قال: لا يكون بدلا مما في ﴿ينصرون﴾؛ لأن ﴿إلا﴾ محقق، والأول منفي، والبدل لا يكون إلا بمعنى الأول. قال: وكذلك لا يجوز أن يكون مستأنفا؛ لأنه لا يستأنف بالاستثناء", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 46, "title": "تأويل: ﴿كغلي الحميم﴾", "tabari": {"page": "21/59", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿كغلي الحميم﴾. يقول: يغلى ذلك في بطون هؤلاء الأشقياء، كغلي الماء المحموم، وهو المسخن الذي قد أوقد عليه حتى تناهت شدة حره.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "حميم. وهو محموم؛ لأنه مصروف من \"مفعول\" إلى \"فعيل\"، كم يقال: قتيل. من مقتول", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 53, "title": "تأويل: ﴿يلبسون من سندس﴾", "tabari": {"page": "21/64", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿يلبسون من سندس﴾. يقول: يلبس هؤلاء المتقون في هذه الجنات من سندس، وهو ما رق من الديباج، ﴿وإستبرق﴾. وهو ما غلظ من الديباج.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿يلبسون من سندس وإستبرق﴾. ولم يقل: لباسا. استغناء بدلالة الكلام على معناه", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5930, "mi": 0, "aya": 54, "alam": "ابن جرير", "fil": "انتقد", "kind": "نقد", "ref": "21/ 65 - 66", "qawl": "مجاهد", "nass": "وهذا الذي قاله مجاهد من أن الحور إنما معناها: أنه يحار فيها الطرف. قول لا معنى له في كلام العرب؛ لأن الحور إنما هو جمع حوراء، كالحمر جمع حمراء، والسود: جمع سوداء، والحوراء إنما هي فعلاء من الحور، وهو نقاء البياض، كما قيل للنقي البياض من الطعام: الحواري. وقد بينا معنى ذلك بشواهده فيما مضى قبل، وبنحو الذي قلنا في معنى ذلك قال سائر أهل التأويل", "qawaid": ["اللغة", "أقوال السلف", "القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 5930, "mi": 0, "aya": 54, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 443", "qawl": "مجاهد", "nass": "وهذا من الاتفاق، وليست اللفظة مشتقة من الحيرة", "qawaid": [], "tabi": ""}], "mushid": {"i": 8, "imgs": ["044_008_1.png"], "pages": [466], "n": 2, "rajih": [1], "daif": [2], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]], "2": [["ابن جرير", "d"]]}, "gen": [], "rules": {}, "rulesD": {"ابن جرير": ["اللغة", "أقوال السلف", "القراءة ورسم المصحف"]}}}], "extra": [], "others": {"0": [{"id": 5899, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 569): «هذه السورة مكية، لا أحفظ خلافًا في شيء منها».", "mawaqif": [{"taliq": 5899, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 569", "qawl": "", "nass": "هذه السورة مكية، لا أحفظ خلافا في شيء منها", "qawaid": [], "tabi": ""}]}], "10": [{"id": 5903, "kinds": "نقد", "text": "انتقد ابنُ كثير (12/ 336) قول الأعرج بقوله: «وهذا قول غريب جدًّا، بل منكر».", "mawaqif": [{"taliq": 5903, "mi": 0, "aya": 10, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "12/ 336", "qawl": "الأعرج بقوله", "nass": "وهذا قول غريب جدا، بل منكر", "qawaid": [], "tabi": ""}]}], "15": [{"id": 5906, "kinds": "ترجيح،بيان", "text": "لما رجّح ابنُ جرير فيما سبق أن الدُّخان: الضرُّ النازل بكفار قريش من الجوع والقحط الذي بلغ من شدته أنهم رأوا في السماء كهيئة الدخان؛ رجَّح (21/ 23 - 24) هنا أنّ العذاب المراد كشفه: هو ذلك الضرّ النازل بهم. لدلالة السياق، ثم بيّن أنه على القول بأنه دخان يكون قبل قيام الساعة؛ فالعذاب المراد كشفه: هو الدُّخان.", "mawaqif": [{"taliq": 5906, "mi": 0, "aya": 15, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "بأنه دخان", "nass": "", "qawaid": ["السياق"], "tabi": ""}]}], "16": [{"id": 5907, "kinds": "خلاف،ترجيح،بيان،نقل", "text": "اختلف المفسرون في البطشة الكبرى بحسب اختلافهم السالف ذكره في وقت الدُّخان والمراد منه، فالقائلون بأنه مضى وأنه ما نزل بكفار قريش من القحط والجوع فسّروا البطشة الكبرى بيوم بدر، والقائلون بأنه دُخان يكون قبل قيام الساعة فسّروا البطشة الكبرى بأنها يوم القيامة. هذا حاصل ما قرره ابنُ جرير (21/ 28).\nوبنحوه ابنُ كثير (12/ 340) فقال: «وقوله تعالى: {يَوْمَ نَبْطِشُ البَطْشَةَ الكُبْرى إنّا مُنْتَقِمُونَ} فسّر ذلك ابن مسعود بيوم بدر. وهذا قول جماعة ممن وافق ابن مسعود على تفسيره الدُّخان بما تقدم، ورُوي أيضًا عن ابن عباس [وجماعة] من رواية العوفي، عنه، وعن أُبي بن كعب وجماعة، وهو محتمل».\nثم رجَّح أنّ البطشة الكبرى: يوم القيامة، وأنّ القول بأنها يوم بدر داخل تحت مدلول البطشة، فقال: «والظاهر أنّ ذلك يوم القيامة، وإن كان يوم بدر يوم بطشة أيضًا».", "mawaqif": []}], "17": [{"id": 5908, "kinds": "تعليق", "text": "علَّق ابنُ عطية (7/ 573) على قول قتادة بأن الرسول الكريم أُريِد به موسى عليه السلام بقوله: «ومعنى الآية يعطي ذلك بلا خلاف».", "mawaqif": [{"taliq": 5908, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 573", "qawl": "قتادة بأن", "nass": "ومعنى الآية يعطي ذلك بلا خلاف", "qawaid": [], "tabi": ""}]}], "19": [{"id": 5910, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (21/ 31) غير قول قتادة، وابن عباس.", "mawaqif": []}], "24": [{"id": 5912, "kinds": "نقد،بيان،تعليق،نقل", "text": "أفاد قول قتادة أنّ الله إنما قال هذا لموسى بعدما قطع البحر ببني إسرائيل، وقد ذكر ابنُ جرير (21/ 34) هذا عن قتادة، ثم علّق عليه قائلًا: «فإذ كان ذلك كذلك ففي الكلام محذوف، وهو: فسَرى موسى بعبادي ليلًا، وقطع بهم البحر، فقلنا له بعد ما قطعه، وأراد ردّ البحر إلى هيئته التي كان عليها قبل انفلاقه: اتركه رهوًا». وذكر أنّ فرقة قالت: هو كلام متصل، أي: إنكم متبعون واترك البحر إذا انفرق لك رهوًا.", "mawaqif": [{"taliq": 5912, "mi": 0, "aya": 24, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "21/ 34", "qawl": "", "nass": "فإذ كان ذلك كذلك ففي الكلام محذوف، وهو: فسرى موسى بعبادي ليلا، وقطع بهم البحر، فقلنا له بعد ما قطعه، وأراد رد البحر إلى هيئته التي كان عليها قبل انفلاقه: اتركه رهوا", "qawaid": [], "tabi": ""}]}], "25": [{"id": 5914, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 576) أن «العيون» تحتمل احتمالين: الأول: أنه أراد الخلجان الخارجة من النيل، فشبّهها بالعيون. الثاني: أنه كانت ثَم عيون ونضبت، كما يعتري في كثير من بقاع الأرض.", "mawaqif": [{"taliq": 5914, "mi": 0, "aya": 25, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 576", "qawl": "", "nass": "العيون", "qawaid": [], "tabi": ""}]}], "27": [{"id": 5916, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (21/ 40) في معنى {فاكهين} غير ما جاء في قول قتادة.", "mawaqif": []}], "28": [{"id": 5917, "kinds": "نقد،بيان", "text": "انتقد ابنُ عطية (7/ 577) هذا القول الذي قاله قتادة، ومقاتل -مستندًا إلى دلالة التاريخ-، فقال: «وهذا ضعيف؛ لأنه لم يُروَ أنّ بني إسرائيل رجعوا إلى مصر في شيء مِن ذلك الزمان، ولا ملكوها قط، إلا أن يريد قتادة أنهم ورثوا نوعها في بلاد الشام». وبيّن أن الذين أورثوا مَن مَلك مصر بعد القبط.", "mawaqif": [{"taliq": 5917, "mi": 0, "aya": 28, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 577", "qawl": "", "nass": "وهذا ضعيف؛ لأنه لم يرو أن بني إسرائيل رجعوا إلى مصر في شيء من ذلك الزمان، ولا ملكوها قط، إلا أن يريد قتادة أنهم ورثوا نوعها في بلاد الشام", "qawaid": ["التاريخ والواقع"], "tabi": ""}]}], "29": [{"id": 5918, "kinds": "نقد،بيان", "text": "انتقد ابنُ كثير (12/ 345) -مستندًا إلى دلالة العقل، والتاريخ- ما جاء في قول يزيد من احمرار أُفق السماء، فقال: «وذكروا أيضًا في مقتل الحسين أنه ما قُلب حجر يومئذ إلا وُجد تحته دم عبيط، وأنه كُسفت الشمس، واحمرّ الأُفق، وسقطت حجارة. وفي كلّ مِن ذلك نظر، والظاهر أنه مِن سخَف الشيعة وكذبهم؛ ليعظّموا الأمر -ولا شك أنه عظيم-، ولكن لم يقع هذا الذي اختلقوه وكذبوه، وقد وقع ما هو أعظم مِن ذلك ولم يقع شيء مما ذكروه، فإنه قد قُتل أبوه علي بن أبي طالب، وهو أفضل منه بالإجماع، ولم يقع شيء من ذلك، وعثمان بن عفان قُتل محصورًا مظلومًا، ولم يكن شيء من ذلك، وعمر بن الخطاب? قُتل في المحراب في صلاة الصبح، وكأن المسلمين لم تطرقهم مصيبة قبل ذلك، ولم يكن شيء من ذلك. وهذا رسول الله صلى الله عليه وسلم وهو سيّد البشر في الدنيا والآخرة يوم مات لم يكن شيء مما ذكروه. ويوم مات إبراهيم بن النبي صلى الله عليه وسلم خُسفت الشمس، فقال الناس: الشمس خُسفت لموت إبراهيم، فصلى بهم رسول الله صلى الله عليه وسلم صلاة الكسوف، وخطبهم وبيّن لهم أن الشمس والقمر لا ينخسفان لموت أحد ولا لحياته».", "mawaqif": [{"taliq": 5918, "mi": 0, "aya": 29, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "12/ 345", "qawl": "يزيد من", "nass": "وذكروا أيضا في مقتل الحسين أنه ما قلب حجر يومئذ إلا وجد تحته دم عبيط، وأنه كسفت الشمس، واحمر الأفق، وسقطت حجارة. وفي كل من ذلك نظر، والظاهر أنه من سخف الشيعة وكذبهم؛ ليعظموا الأمر -ولا شك أنه عظيم-، ولكن لم يقع هذا الذي اختلقوه وكذبوه، وقد وقع ما هو أعظم من ذلك ولم يقع شيء مما ذكروه، فإنه قد قتل أبوه علي بن أبي طالب، وهو أفضل منه بالإجماع، ولم يقع شيء من ذلك، وعثمان بن عفان قتل محصورا مظلوما، ولم يكن شيء من ذلك، وعمر بن الخطاب? قتل في المحراب في صلاة الصبح، وكأن المسلمين لم تطرقهم مصيبة قبل ذلك، ولم يكن شيء من ذلك. وهذا رسول الله صلى الله عليه وسلم وهو سيد البشر في الدنيا والآخرة يوم مات لم يكن شيء مما ذكروه. ويوم مات إبراهيم بن النبي صلى الله عليه وسلم خسفت الشمس، فقال الناس: الشمس خسفت لموت إبراهيم، فصلى بهم رسول الله صلى الله عليه وسلم صلاة الكسوف، وخطبهم وبين لهم أن الشمس والقمر لا ينخسفان لموت أحد ولا لحياته", "qawaid": ["الدلالة العقلية", "التاريخ والواقع"], "tabi": ""}]}, {"id": 5919, "kinds": "ترجيح،نقد،نقل", "text": "ذكر ابنُ عطية (7/ 578) ما جاء في آثار السلف من بكاء السماء والأرض على الصالحين، وما ورد أن بكاء السماء حمرتها، ثم رجّح -مستندًا إلى النظائر- أنّ البكاء مستعار لتحقير أمرهم، فقال: «المعنى الجيد في الآية أنها استعارة باهية فصيحة تتضمن تحقير أمرهم، وأنهم لم يتغيّر عن هلاكهم شيء، وهذا نحو قوله تعالى: {وإن كان مكرهم لتزول} [إبراهيم: 46] على قراءة من قرأ: {لتزول} بكسر اللام ونصب الفعل، وجعل {إن} نافية، ومثل هذا المعنى قول النبي عليه السلام: «لا ينتطح فيها عنزان». فإنه يتضمن التحقير».", "mawaqif": [{"taliq": 5919, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 578", "qawl": "", "nass": "المعنى الجيد في الآية أنها استعارة باهية فصيحة تتضمن تحقير أمرهم، وأنهم لم يتغير عن هلاكهم شيء، وهذا نحو قوله تعالى: {وإن كان مكرهم لتزول} [إبراهيم: 46] على قراءة من قرأ: {لتزول} بكسر اللام ونصب الفعل، وجعل {إن} نافية، ومثل هذا المعنى قول النبي عليه السلام: «لا ينتطح فيها عنزان", "qawaid": ["القرآن والنظائر"], "tabi": ""}]}], "42": [{"id": 5922, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 582): «قوله: {ولا هُمْ يُنْصَرُونَ} إن كان الضمير يُراد به: العالم، فيصح أن تكون {مَن} في قوله: {إلا من رحم الله} في موضع نصب على الاستثناء المتصل. وإن كان الضمير يراد به: الكفار، فالاستثناء منقطع، ويصح أنْ يكون في موضع رفع على الابتداء، والخبر مقدر، تقديره: فإنه يغني بعضهم عن بعض في الشفاعة ونحوها. أو يكون تقديره: فإنّ الله ينصره».", "mawaqif": [{"taliq": 5922, "mi": 0, "aya": 42, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 582", "qawl": "", "nass": "قوله: {ولا هم ينصرون} إن كان الضمير يراد به: العالم، فيصح أن تكون {من} في قوله: {إلا من رحم الله} في موضع نصب على الاستثناء المتصل. وإن كان الضمير يراد به: الكفار، فالاستثناء منقطع، ويصح أن يكون في موضع رفع على الابتداء، والخبر مقدر، تقديره: فإنه يغني بعضهم عن بعض في الشفاعة ونحوها. أو يكون تقديره: فإن الله ينصره", "qawaid": [], "tabi": ""}]}, {"id": 5923, "kinds": "بيان،نقل", "text": "ذكر ابنُ عطية (3/ 76) أثر أبي الدراداء، وبيّن أنّ هذا منه? على جهة التفسير، وليست قراءة.", "mawaqif": [{"taliq": 5923, "mi": 0, "aya": 42, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "3/ 76", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 5924, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 582) قول ابن زيد، ثم قال معلّقًا: «ثم هي بالمعنى تتناول كلَّ أثيم، وهو كلّ فاجر يكتسب الإثم».\nوبنحوه ابنُ كثير (12/ 351) قال: «وذكر غير واحد أنّه أبو جهل، ولا شكّ في دخوله في هذه الآية، ولكن ليست خاصّة به».", "mawaqif": [{"taliq": 5924, "mi": 0, "aya": 42, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 582", "qawl": "ابن زيد", "nass": "ثم هي بالمعنى تتناول كل أثيم، وهو كل فاجر يكتسب الإثم", "qawaid": [], "tabi": ""}, {"taliq": 5924, "mi": 0, "aya": 42, "alam": "ابن كثير", "fil": "وبنحوه", "kind": "موافقة", "ref": "12/ 351", "qawl": "", "nass": "وذكر غير واحد أنه أبو جهل، ولا شك في دخوله في هذه الآية، ولكن ليست خاصة به", "qawaid": [], "tabi": "ابن عطية"}]}], "45": [{"id": 5925, "kinds": "توجيه،تعليق،نقل", "text": "ذكر ابنُ جرير (21/ 58) هذه القراءة، ووجّهها، فقال: «قرأته عامة قراء المدينة والبصرة والكوفة «تَغْلِي» بالتاء، بمعنى: أنّ شجرة الزّقوم تغلي في بطونهم، فأنّثوا «تَغْلِي» لتأنيث الشجرة». ثم ذكر قراءة من قرأ ذلك بالياء، ووجّهها، فقال: «وقرأ ذلك بعض قراء أهل الكوفة {يغلي} بمعنى: طعام الأثيم يغلي، أو المُهل يغلي، فذكَّره بعضهم لتذكير الطعام، ووجَّه معناه إلى أنّ الطعام هو الذي يغلي في بطونهم، وبعضُهم لتذكير المُهل، ووجّهه إلى أنه صفة للمُهل الذي يغلي».\nوبنحوه قال ابنُ عطية (7/ 583).\nثم علّق ابنُ جرير على القراءتين بقوله: «والصواب من القول في ذلك أنهما قراءتان معروفتان صحيحتا المعنى، فبأيتهما قرأ القارئ فمصيب».", "mawaqif": [{"taliq": 5925, "mi": 0, "aya": 45, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "21/ 58", "qawl": "", "nass": "قرأته عامة قراء المدينة والبصرة والكوفة «تغلي", "qawaid": [], "tabi": ""}, {"taliq": 5925, "mi": 0, "aya": 45, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 583", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5925, "mi": 0, "aya": 45, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "", "qawl": "", "nass": "والصواب من القول في ذلك أنهما قراءتان معروفتان صحيحتا المعنى، فبأيتهما قرأ القارئ فمصيب", "qawaid": [], "tabi": ""}]}], "47": [{"id": 5926, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (21/ 59) غير قول مجاهد.", "mawaqif": []}, {"id": 5927, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 583 - 584): «والسواء: الوسط. وقيل: المُعْظَم. وذلك متلازم، المُعْظم أبدًا من مثل هذا إنما هو في الوسط».", "mawaqif": [{"taliq": 5927, "mi": 0, "aya": 47, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 583 - 584", "qawl": "", "nass": "والسواء: الوسط. وقيل: المعظم. وذلك متلازم، المعظم أبدا من مثل هذا إنما هو في الوسط", "qawaid": [], "tabi": ""}]}], "51": [{"id": 5928, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (21/ 64) غير قول قتادة.", "mawaqif": []}], "54": [{"id": 5929, "kinds": "توجيه،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 585) قراءة ابن مسعود، وعلّق عليها فقال: «وقرأ ابن مسعود: (عِيسٍ)، وهو جمع عيساء، وهي أيضًا البيضاء، وكذلك هي من النوق».", "mawaqif": [{"taliq": 5929, "mi": 0, "aya": 54, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 585", "qawl": "", "nass": "وقرأ ابن مسعود: (عيس)، وهو جمع عيساء، وهي أيضا البيضاء، وكذلك هي من النوق", "qawaid": [], "tabi": ""}]}], "55": [{"id": 5931, "kinds": "بيان،نقل", "text": "بيّن ابنُ جرير (21/ 67) أن قوله: {آمنين} معناه: «آمنين فيها مِن انقطاع تلك النِّعَم عنهم ونفادها وفنائها، ومن غائلة أذاها ومكروهها». ثم ذكر قول قتادة، ولم يعلّق عليه.", "mawaqif": [{"taliq": 5931, "mi": 0, "aya": 55, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "21/ 67", "qawl": "", "nass": "آمنين فيها من انقطاع تلك النعم عنهم ونفادها وفنائها، ومن غائلة أذاها ومكروهها", "qawaid": [], "tabi": ""}]}], "56": [{"id": 5932, "kinds": "نقد،توجيه،بيان،نقل", "text": "بيّن ابنُ جرير (21/ 67 - 69) أن قوله: {لا يذوقون فيها إلا الموتة الأولى} معناه: «لا يذوق هؤلاء المتّقون في الجنّة الموت بعد الموتة الأولى التي ذاقوها في الدنيا». ثم ذكر عن بعض أهل اللغة أنه وجّه {إلا} في هذا الموضع إلى أنها بمعنى: سوى. وانتقده مستندًا إلى الأغلب من عادة العرب في كلامها، فقال: «وليس للذي قال مِن ذلك عندي وجه مفهوم؛ لأنّ الأغلب من قول القائل: لا أذوق اليوم الطعام إلا الطعام الذي ذقته قبل اليوم. أنه يريد الخبر عن قائله أن عنده طعامًا في ذلك اليوم ذائقه وطاعمه دون سائر الأطعمة غيره، وإذا كان ذلك الأغلب من معناه وجب أن يكون قد أثبت بقوله: {إلا الموتة الأولى} موتة مِن نوع الأولى هم ذائقوها، ومعلوم أنّ ذلك ليس كذلك؛ لأن الله عز وجل قد أمَّن أهل الجنة في الجنة إذا هم دخلوها من الموت، ولكن ذلك كما وصفتُ من معناه، وإنما جاز أن توضع {إلا} في موضع» بعد «لتقارب معنييهما في هذا الموضع».\nواستدرك ابنُ عطية (7/ 585) على ابن جرير في انتقاده هذا القول، فقال: «قدّر قوم {إلّا} بسوى، وضعّف ذلك الطبري، وقدّرها ببعد، وليس تضعيفه بصحيح، بل يصح المعنى بسوى ويَتَّسِق».", "mawaqif": [{"taliq": 5932, "mi": 0, "aya": 56, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "21/ 67 - 69", "qawl": "", "nass": "لا يذوق هؤلاء المتقون في الجنة الموت بعد الموتة الأولى التي ذاقوها في الدنيا", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 5932, "mi": 0, "aya": 56, "alam": "ابن عطية", "fil": "استدرك", "kind": "نقد", "ref": "7/ 585", "qawl": "", "nass": "قدر قوم {إلا} بسوى، وضعف ذلك الطبري، وقدرها ببعد، وليس تضعيفه بصحيح، بل يصح المعنى بسوى ويتسق", "qawaid": [], "tabi": ""}]}]}, "athar": {"69871": {"num": 69871, "aya": 3, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {إنّا أنْزَلْناهُ فِي لَيْلَةٍ مُبارَكَةٍ}، قال: هي ليلة القدر."}, "69872": {"num": 69872, "aya": 3, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {إنّا أنْزَلْناهُ فِي لَيْلَةٍ مُبارَكَةٍ}: ليلة القدر، ونزلت صُحف إبراهيم في أول ليلةٍ مِن رمضان، ونزلت التوراة لستِّ ليالٍ مضَتْ مِن رمضان، ونزل الزّبور لست عشرة مضَتْ مِن رمضان، ونزل الإنجيل لثمان عشرة مضَتْ مِن رمضان، ونزل الفرقان لأربع وعشرين مضَتْ مِن رمضان."}, "69875": {"num": 69875, "aya": 3, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله عز وجل: {إنّا أنْزَلْناهُ فِي لَيْلَةٍ مُبارَكَةٍ}، قال: تلك الليلة ليلة القدر، أنزل الله هذا القرآنَ مِن أُمّ الكتاب في ليلة القدر، ثم أنزله على الأنبياء في الليالي والأيام، وفي غير ليلة القدر."}, "69878": {"num": 69878, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {إنّا أنْزَلْناهُ فِي لَيْلَةٍ مُبارَكَةٍ إنّا كُنّا مُنْذِرِينَ فِيها يُفْرَقُ كُلُّ أمْرٍ حَكِيمٍ}، قال: يُكتب مِن أُمّ الكتاب في ليلة القدر ما يكون في السنة من رزْق، أو موت، أو حياة، أو مطر، حتى يُكتبَ الحُجّاجُ: يحجّ فلان ويحجّ فلان."}, "69879": {"num": 69879, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس: {فِيها يُفْرَقُ كُلُّ أمْرٍ حَكِيمٍ} أنّ الله يقضي الأُقضية في ليلة النّصف من شعبان، ويسلّمها إلى أربابها في ليلة القدر."}, "69880": {"num": 69880, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جُبير- قال: إنّك لَترى الرجلَ يمشي في الأسواق، وقد وقع اسمُه في الموتى. ثم قرأ: {حم والكِتابِ المُبِينِ إنّا أنْزَلْناهُ فِي لَيْلَةٍ مُبارَكَةٍ إنّا كُنّا مُنْذِرِينَ فِيها يُفْرَقُ كُلُّ أمْرٍ حَكِيمٍ}، يعني: ليلة القدر. قال: ففي تلك الليلة يُفْرَق أمر الدنيا إلى مثلها من قابل؛ موت، أو حياة، أو رزْق، كلّ أمر الدنيا يُفْرق تلك الليلة إلى مثلها من قابل."}, "69882": {"num": 69882, "aya": 4, "qail": "أبي عبد الرحمن السلمي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي عبد الرحمن السُّلَمِيّ -من طريق سعيد بن عبيدة- قال: {فِيها يُفْرَقُ كُلُّ أمْرٍ حَكِيمٍ}، يُدبّر أمر السّنة إلى السّنة في ليلة القدر."}, "69884": {"num": 69884, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- أنه سُئِل عن قوله: {فِيها يُفْرَقُ كُلُّ أمْرٍ حَكِيمٍ}. قال: يُفْرَق في ليلة القدر ما يكون في السّنة مِن رزْق أو مصيبة، ثم يُقدّم ما شاء، ويؤخّر ما شاء، فأما كتاب الشقاء والسعادة فإنه ثابت لا يتغيّر."}, "69885": {"num": 69885, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- أنه سُئِل عن قوله: {فِيها يُفْرَقُ كُلُّ أمْرٍ حَكِيمٍ}. قال: في ليلة القدر، كلُّ أمر يكون في السّنة إلى السّنة، إلا الحياة والموت، ويُفْرَق فيها المعايش والمصائب كلّها."}, "69889": {"num": 69889, "aya": 4, "qail": "أبي مالك غزوان الغفاري", "tabaqa": "تابعي", "bab": "", "text": "عن أبي مالك غَزْوان الغِفارِيّ -من طريق سلمة- في قوله: {فِيها يُفْرَقُ كُلُّ أمْرٍ حَكِيمٍ}، قال: عَمَلُ السّنة إلى السّنة."}, "69890": {"num": 69890, "aya": 4, "qail": "أبي مالك غزوان الغفاري", "tabaqa": "تابعي", "bab": "", "text": "عن أبي مالك غَزْوان الغِفارِيّ -من طريق سفيان الثوري- في قوله: {فيها يفرق كل أمر حكيم}، قال: أمر السّنة إلى السّنة. قال: ما كان مِن خلْق، أو أجَل، أو رزْق، أو مصيبة، أو نحو هذا."}, "69894": {"num": 69894, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: {فِيها يُفْرَقُ كُلُّ أمْرٍ حَكِيمٍ} فيها يُفْرق أمر السّنة إلى السّنة. وفي لفظ قال: فيها يُقضى ما يكون مِن السّنة إلى السّنة."}, "69903": {"num": 69903, "aya": 10, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {فارْتَقِبْ}: أي: فانتَظِر."}, "69905": {"num": 69905, "aya": 10, "qail": "حذيفة بن اليمان", "tabaqa": "صحابي", "bab": "", "text": "عن حُذيفة بن اليمان مرفوعًا: «أولُ الآيات: الدَّجّال، ونزول عيسى ابن مريم، ونار تَخرج مِن قعْر عدَن أبْيَن تسوق الناس إلى المحشر، تَقِيل معهم إذا قالوا، والدّخان». قال حذيفة: يا رسول الله، وما الدّخان؟ فتلا رسولُ الله صلى الله عليه وسلم: «{فارْتَقِبْ يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ} يملأ ما بين المشرق والمغرب، يمكث أربعين يومًا وليلة، أمّا المؤمن فيصيبه منه كهيئة الزُّكْمة، وأمّا الكافر بمنزلة السّكران يخرج مِن مَنخريه وأُذُنيه ودُبره»."}, "69906": {"num": 69906, "aya": 10, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق أبي عبيدة- قال: آية الدُّخان قد مضت."}, "69907": {"num": 69907, "aya": 10, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق أبي الأحوص، وأبي عبيدة-: الدُّخانُ جوعٌ أصاب قريشًا، حتى كان أحدُهم لا يبصر السماءَ مِن الجوع."}, "69908": {"num": 69908, "aya": 10, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق عتبة- قال: الدّخان قد مضى، كان أناسٌ أصابهم مَخْمصة وجوع شديد، حتى كانوا يرون الدُّخان فيما بينهم وبين السماء."}, "69909": {"num": 69909, "aya": 10, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق مسروق- قال: خمسٌ قد مضين: الدخان، والقمر، والروم، والبطشة، واللِّزام."}, "69910": {"num": 69910, "aya": 10, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن مسعود -من طريق محمد بن سيرين-: كلّ ما وعدنا الله ورسوله فقد رأيناه، غير أربع: طلوع الشمس من مغربها، والدَّجّال، ودابّة الأرض، ويأجوج ومأجوج؛ فأما الدُّخان فقد مضى وكان سنين كسني آل يوسف، وأما القمر فقد انشقّ على عهد رسول الله صلى الله عليه وسلم، وأما البطْشة الكُبرى فيوم بدر."}, "69911": {"num": 69911, "aya": 10, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق أبي وائل- {فارْتَقِبْ يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ}، قال: جوع أصاب الناس بمكة."}, "69912": {"num": 69912, "aya": 10, "qail": "قتادة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة: {يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ}، قال: كان ابن مسعود يقول: قد مضى الدُّخان، وكان سنين كسني يوسف {يَغْشى النّاسَ هَذا عَذابٌ ألِيمٌ}."}, "69913": {"num": 69913, "aya": 10, "qail": "ابن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن ابن مسعود، قال: لما رأى رسول الله صلى الله عليه وسلم مِن الناس إدبارًا قال: «اللهم، سبْعٌ كسبْع يوسف». فأخذتْهم سَنة حتى أكلوا الميتة والجلود والعظام، فجاءه أبو سفيان وناسٌ من أهل مكة، فقالوا: يا محمد، إنّك تزعمُ أنّك قد بُعِثتَ رحمةً، وإنّ قومك قد هلكوا؛ فادعُ الله لهم. فدعا رسولُ الله صلى الله عليه وسلم، فسُقوا الغيث، فأطبقتْ عليهم سبْعًا، فشكا الناسُ كثرة المطر، فقال: «اللهم، حَواليْنا ولا علينا». فانحدرت السحابة على رأسه، فسُقي الناس حولهم، قال: لقد مضتْ آية الدُّخان، وهو الجوع الذي أصابهم، وهو قوله: {إنّا كاشِفُو العَذابِ قَلِيلًا إنَّكُمْ عائِدُونَ} [الدخان: 15]، وآية اللّزام، والبطْشة الكُبرى، وانشقاق القمر، وذلك كلّه يوم بدر."}, "69914": {"num": 69914, "aya": 10, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق مسروق- أن رجلًا جاءه، فقال: إني تركتُ رجلًا في المسجد يقول في هذه الآية: {فارْتَقِبْ يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ يَغْشى النّاسَ هَذا عَذابٌ ألِيمٌ}: يغشى الناسَ يوم القيامة دُخان، فيأخذ بأسماع المنافقين وأبصارهم، ويأخذ المؤمن منه كهيئة الزّكام. فغضب، وكان مُتَّكئًا فجلس، ثم قال: مَن علِم منكم علمًا فليقُل به، ومَن لم يكن يعلم فليقُل: الله أعلم. فإنّ مِن العلم أن يقول لما لا يعلم: الله أعلم. وسأحدّثكم عن الدُّخان: إنّ قريشًا لما استصعبت على رسول الله صلى الله عليه وسلم وأبطؤوا عن الإسلام قال: «اللهم، أعِنِّي عليهم بسبْعٍ كسبْع يوسف». فأصابهم قَحْط وجَهد، حتى أكلوا العظام، فجعل الرجلُ ينظر إلى السماء فيرى ما بينه وبينها كهيئة الدُّخان من الجوع؛ فأنزل الله: {فارْتَقِبْ يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ يَغْشى النّاسَ هَذا عَذابٌ ألِيمٌ}. فأُتِي النبيُّ صلى الله عليه وسلم، فقيل: يا رسول الله، استَسقِ الله لِمُضَر. فاستسقى لهم، فسُقوا؛ فأنزل الله: {إنّا كاشِفُو العَذابِ قَلِيلًا إنَّكُمْ عائِدُونَ} [الدخان: 15] أفيُكشف عنهم العذاب يوم القيامة؟ فلما أصابتهم الرّفاهية عادوا إلى حالهم؛ فأنزل الله: {يَوْمَ نَبْطِشُ البَطْشَةَ الكُبْرى إنّا مُنْتَقِمُونَ} [الدخان: 16]، فانتقم الله منهم يوم بدر؛ فقد مضى البطْشة، والدُّخان، واللزام."}, "69915": {"num": 69915, "aya": 10, "qail": "عاصم", "tabaqa": "تابعي", "bab": "", "text": "عن عاصم، قال: شهدتُ جنازة فيها زيد بن علي، فأنشأ يحدّث يومئذ، فقال: إنّ الدُّخان يجيء قبل يوم القيامة، فيأخذ بأنفِ المؤمن الزّكام، ويأخذ بمسامع الكافر. قال: قلتُ: رحمك الله، إنّ صاحبنا عبد الله قد قال غيرَ هذا، قال: إنّ الدُّخان قد مضى. وقرأ هذه الآية: {فارْتَقِبْ يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ يَغْشى النّاسَ هَذا عَذابٌ ألِيمٌ}. قال: أصاب الناس جَهد حتى جعل الرجل يرى ما بينه وبين السماء دُخانًا، فذلك قوله: {فارْتَقِبْ}، وكذا قرأ عبد الله إلى قوله: {إنّا مُؤْمِنُونَ}، قال: {إنّا كاشِفُو العَذابِ قَلِيلًا} [الدخان: 15]. قلت لزيد: فعادوا، فأعاد الله عليهم بدرًا، فذلك قوله: {وإنْ عُدْتُمْ عُدْنا} [الإسراء: 8]، فذلك يوم بدر. قال: فقَبل، واللهِ. قال عاصم: فقام رجلٌ يَردّ عليه، فقال زيد: أما إنّ رسول الله صلى الله عليه وسلم قد قال: «إنكم سيجيئكم رواة، فما وافق القرآن فخذوا به، وما كان غير ذلك فدعوه»."}, "69916": {"num": 69916, "aya": 10, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "", "text": "عن علي بن أبي طالب -من طريق الحارث- قال: إنّ الدُّخان لم يمضِ بعدُ، يأخذ المؤمن كهيئة الزّكام، وينفخ الكافر حتى ينفُذ."}, "69917": {"num": 69917, "aya": 10, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هُريرة -من طريق الأعرج- قال: كان يومُ فتح مكة دُخان، وهو قول الله: {فارْتَقِبْ يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ}."}, "69918": {"num": 69918, "aya": 10, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: {فارْتَقِبْ يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ} هو دُخان يجيء قبل قيام الساعة، ولم يأتِ بعدُ، فيدخل في أسماع الكُفّار والمنافقين حتى يكون كالرأس الحَنِيذ، ويعتري المؤمنُ منه كهيئة الزّكام، وتكون الأرض كلّها كبيت أُوقِد فيه النار."}, "69920": {"num": 69920, "aya": 10, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عمر -من طريق عبد الرحمن بن البيلماني- قال: يخرج الدُّخان، فيأخذ المؤمن كهيئة الزّكْمة، ويدخل في مسامع الكافر والمنافق، حتى يكون كالرأس الحنيذ."}, "69921": {"num": 69921, "aya": 10, "qail": "أبي سعيد الخدري", "tabaqa": "صحابي", "bab": "", "text": "عن أبي سعيد الخدري -من طريق الحسن- قال: يهيج الدُّخان بالناس، فأمّا المؤمن فيأخذه كهيئة الزّكْمة، وأما الكافر فيَنفُخه حتى يخرج من كل مِسمع منه."}, "69922": {"num": 69922, "aya": 10, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرِّياحي -من طريق عوف- قال: مضى الدُّخان، والبطْشة الكُبرى يوم بدر."}, "69923": {"num": 69923, "aya": 10, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النَّخعي -من طريق مغيرة- قال: {يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ} مضى الدُّخان لسنين أصابتهم."}, "69924": {"num": 69924, "aya": 10, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {فارْتَقِبْ يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ}، قال: الجدْب، وإمساك المطر عن كفار قريش."}, "69925": {"num": 69925, "aya": 10, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق عبيد- {يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ}: قد مضى شأن الدُّخان."}, "69926": {"num": 69926, "aya": 10, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق عوف- قال: الدُّخان قد بقي، وهو من الآيات، فإذا جاء الدخان نفخ الكافرَ، حتى يخرج مِن كلِّ سمع من مسامعه، ويأخذ المؤمن كزَكْمة."}, "69927": {"num": 69927, "aya": 10, "qail": "الأعرج", "tabaqa": "تابعي", "bab": "", "text": "عن الأعرج -من طريق ابن لهيعة- {يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ}، قال: كان يوم فتح مكة."}, "69928": {"num": 69928, "aya": 10, "qail": "مقاتل بن سليمان", "tabaqa": "تابع التابعين", "bab": "", "text": "قال مقاتل بن سليمان: {فارْتَقِبْ} … وذلك أنّ النبي صلى الله عليه وسلم دعا اللهَ على كفار قريش، فقال: «اللهم، أعِنِّي عليهم بسبْع سنين كسني يوسف». فأصابتهم شِدّة، حتى أكلوا العظام والكلاب والجِيَف مِن شِدّة الجوع، فكان الرجل يرى بينه وبين السماء الدُّخان من الجوع، فذلك قوله: {فارْتَقِبْ} يقول: فانتَظِر، يا محمد {يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ} عذاب أليم، {يَغْشى النّاسَ} يعني: أهل مكة، {هَذا} الجوع {عَذابٌ ألِيمٌ} يعني: وجيع."}, "69929": {"num": 69929, "aya": 10, "qail": "أبي مالك الأشعري", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن أبي مالك الأشعري، قال: قال رسول الله صلى الله عليه وسلم: «إنّ ربكم أنذركم ثلاثًا: الدُّخان، يأخذ المؤمن منه كالزَّكْمة، ويأخذ الكافر فيَنتَفِخ حتى يخرج من كلّ مِسْمع منه، والثانية الدابّة، والثالثة الدَّجّال»."}, "69930": {"num": 69930, "aya": 10, "qail": "أبي سعيد الخدري", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن أبي سعيد الخُدري، أنّ رسول الله صلى الله عليه وسلم قال: «يَهيج الدُّخان بالناس، فأما المؤمن فيأخذه كالزَّكْمة، وأما الكافر فيَنفُخه حتى يخرج من كلّ مِسْمع منه»."}, "69931": {"num": 69931, "aya": 10, "qail": "الحسن", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن الحسن، قال: بلغني: أنّ رسول الله صلى الله عليه وسلم قال: «إنّ الدُّخان إذا جاء نفخ الكافرَ حتى يخرج مِن كل مِسمع من مسامعه، ويأخذ المؤمن منه كالزَّكْمة»."}, "69946": {"num": 69946, "aya": 16, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق مسروق-: … لَمّا أصابتهم الرّفاهية عادوا إلى حالهم؛ فأنزل الله: {يَوْمَ نَبْطِشُ البَطْشَةَ الكُبْرى إنّا مُنْتَقِمُونَ}، فانتقم الله منهم يومَ بدر، فقد مضى البطْشة، والدُّخان، واللزام."}, "69947": {"num": 69947, "aya": 16, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طرق- أنه قال: {يَوْمَ نَبْطِشُ البَطْشَةَ الكُبْرى إنّا مُنْتَقِمُونَ}، قال: يوم بدر."}, "69948": {"num": 69948, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: {يَوْمَ نَبْطِشُ البَطْشَةَ الكُبْرى إنّا مُنْتَقِمُونَ}، قال ابن مسعود: البطْشة الكُبرى يوم بدر. ="}, "69950": {"num": 69950, "aya": 16, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النَّخْعي -من طريق الأعمش- {يَوْمَ نَبْطِشُ البَطْشَةَ الكُبْرى}، قال: مرّ بي عكرمة، فسألتُه عن البطْشة الكُبرى، فقال: يوم القيامة. ="}, "69952": {"num": 69952, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العَوفيّ-، مثله."}, "69953": {"num": 69953, "aya": 16, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "", "text": "عن أُبيّ بن كعب -من طريق مجاهد- ="}, "69957": {"num": 69957, "aya": 16, "qail": "محمد بن سيرين", "tabaqa": "تابعي", "bab": "", "text": "ومحمد بن سيرين ="}, "69959": {"num": 69959, "aya": 16, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "وقتادة بن دعامة، مثله."}, "69960": {"num": 69960, "aya": 16, "qail": "مسروق بن الأجدع الهمداني", "tabaqa": "تابعي", "bab": "", "text": "عن مسروق بن الأجْدع الهَمْدانِيّ -من طريق مسلم- قال: {البَطْشَةَ الكُبْرى} يوم بدر."}, "69963": {"num": 69963, "aya": 16, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {يَوْمَ نَبْطِشُ البَطْشَةَ الكُبْرى} قال: يوم بدر."}, "69968": {"num": 69968, "aya": 16, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {يَوْمَ نَبْطِشُ البَطْشَةَ الكُبْرى}، قال: هذا يوم بدر."}, "69981": {"num": 69981, "aya": 20, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {أنْ تَرْجُمُونِ}، قال: تشتمون."}, "69982": {"num": 69982, "aya": 20, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- في قوله: {أنْ تَرْجُمُونِ} قال: رجم القول."}, "69983": {"num": 69983, "aya": 20, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {وإنِّي عُذْتُ بِرَبِّي ورَبِّكُمْ أنْ تَرْجُمُون}، قال: بالحجارة."}, "69984": {"num": 69984, "aya": 20, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "", "text": "عن أبي صالح باذام -من طريق شعبة، عن إسماعيل- في قوله: {وإنِّي عُذْتُ بِرَبِّي ورَبِّكُمْ أنْ تَرْجُمُونِ}، قال: الرّجم بالقول."}, "69985": {"num": 69985, "aya": 20, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "", "text": "عن أبي صالح باذام -من طريق سفيان، عن إسماعيل- في قوله: {وإنِّي عُذْتُ بِرَبِّي ورَبِّكُمْ أنْ تَرْجُمُونِ}، قال: أن تقولوا: هو ساحر."}, "69993": {"num": 69993, "aya": 24, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {رَهْوًا}، قال: سَمْتًا."}, "69994": {"num": 69994, "aya": 24, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، {واتْرُكِ البَحْرَ رَهْوًا}، قال: كهيئته، وامضِهْ."}, "69995": {"num": 69995, "aya": 24, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، {واتْرُكِ البَحْرَ رَهْوًا}، قال: دَمِثًا."}, "69996": {"num": 69996, "aya": 24, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- {واتْرُكِ البَحْرَ رَهْوًا}، قال: الرَّهو: أن يُترك كما كان، فإنهم لن يَخْلُصوا من ورائه."}, "69997": {"num": 69997, "aya": 24, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- قوله: {واتْرُكِ البَحْرَ رَهْوًا}، قال: يقال: الرَّهو: السهل."}, "69998": {"num": 69998, "aya": 24, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن ابن عباس، أنّه سأل كعبًا عن قوله: {واتْرُكِ البَحْرَ رَهْوًا}. قال: طريقًا."}, "69999": {"num": 69999, "aya": 24, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {رَهْوًا}، قال: طريقًا منفرجًا."}, "70000": {"num": 70000, "aya": 24, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "قال مجاهد بن جبر: {واتْرُكِ البَحْرَ رَهْوًا}، يعني: ساكنًا بعد أن ضربه موسى بعصاه."}, "70001": {"num": 70001, "aya": 24, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {واتْرُكِ البَحْرَ رَهْوًا}، قال: طريقًا يابسًا، كهيئته يوم ضربه. يقول: لا تأمره أن يرجع، بل اتركه حتى يدخل آخرهم."}, "70002": {"num": 70002, "aya": 24, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق عبيد- في قوله: {واتْرُكِ البَحْرَ رَهْوًا}، قال: سهلًا دَمِثًا."}, "70008": {"num": 70008, "aya": 24, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة، في قوله: {واتْرُكِ البَحْرَ رَهْوًا}، قال: ساكنًا."}, "70009": {"num": 70009, "aya": 24, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- قال: لما قطع موسى البحرَ عطف ليضرب البحرَ بعصاه ليلتئم، وخاف أن يتبعه فرعونُ وجنوده، فقيل له: {واتْرُكِ البَحْرَ رَهْوًا} يقول: كما هو طريقًا يابسًا؛ {إنَّهُمْ جُنْدٌ مُغْرَقُونَ}."}, "70011": {"num": 70011, "aya": 24, "qail": "الربيع بن أنس", "tabaqa": "تابعي", "bab": "", "text": "عن الربيع بن أنس -من طريق أبي جعفر- {واتْرُكِ البَحْرَ رَهْوًا}، قال: سهلًا."}, "70013": {"num": 70013, "aya": 24, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {واتْرُكِ البَحْرَ رَهْوًا}، قال: هو السّهل."}, "70017": {"num": 70017, "aya": 26, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جُبير -من طريق سالم الأفطس-، مثله."}, "70018": {"num": 70018, "aya": 26, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق مهاجر-، مثله."}, "70019": {"num": 70019, "aya": 26, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {ومَقامٍ كَرِيمٍ}، قال: مقام حسن."}, "70030": {"num": 70030, "aya": 29, "qail": "شريح بن عبيد الحضرمي مرسلا", "tabaqa": "", "bab": "", "text": "عن شُرَيْح بن عبيد الحضرمي مرسلًا، قال: قال رسول الله صلى الله عليه وسلم: «إنّ الإسلام بدأ غريبًا، وسيعود غريبًا، ألا لا غُربة على مؤمن، ما مات مؤمن في غُربة غابتْ عنه فيها بواكيه، إلا بَكتْ عليه السماء والأرض». ثم قرأ رسول الله صلى الله عليه وسلم: {فَما بَكَتْ عَلَيْهِمُ السَّماءُ والأَرْضُ وما كانُوا مُنْظَرِين}. ثم قال: «إنهما لا يبكيان على كافر»."}, "70033": {"num": 70033, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- في قوله: {فَما بَكَتْ عَلَيْهِمُ السَّماءُ والأَرْضُ} الآية، قال: ذلك أنّه ليس على الأرض مؤمن يموت إلا بكى عليه ما كان يصلّي فيه مِن المساجد حين يَفْقده، وإلا بكى عليه من السماء الموضع الذي كان يُرفع منه كلامه، فذلك قوله لأهل معصيته: {فَما بَكَتْ عَلَيْهِمُ السَّماءُ والأَرْضُ وما كانُوا مُنْظَرِين}؛ لأنهما يبكيان على أولياء الله."}, "70034": {"num": 70034, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جُبير- أنه سُئل عن قوله: {فَما بَكَتْ عَلَيْهِمُ السَّماءُ والأَرْضُ} هل تبكي السماء والأرض على أحد؟ قال: نعم، إنه ليس أحد مِن الخلائق إلا له باب في السماء، منه ينزل رزْقه، وفيه يصعد عمله، فإذا مات المؤمن فأُغلق بابه في السماء؛ فقَدَه، فبكى عليه، وإذا فقَدَه مصلاه من الأرض التي كان يصلّي فيها ويذكر الله فيها بكتْ عليه، وإنّ قوم فرعون لم يكن لهم في الأرض آثار صالحة، ولم يكن يصعد إلى الله منهم خير، فلم تبكِ عليهم السماء والأرض."}, "70035": {"num": 70035, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق مجاهد- قال: إنّ الأرض لتبكي على المؤمن أربعين صباحًا. ثم قرأ: {فَما بَكَتْ عَلَيْهِمُ السَّماءُ والأَرْضُ}."}, "70037": {"num": 70037, "aya": 29, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جُبير، {فَما بَكَتْ عَلَيْهِمُ السَّماءُ والأَرْضُ}، قال: لم تبكِ عليهم السماءِ؛ لأنهم لم يكونوا يُرفع لهم فيها عمل صالح، ولم تبكِ عليهم الأرض؛ لأنهم لم يكونوا يعملون فيها بعملٍ صالح."}, "70038": {"num": 70038, "aya": 29, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جُبير -من طريق قتادة- أنه كان يقول: {فَما بَكَتْ عَلَيْهِمُ السَّماءُ والأَرْضُ} إنّ بقاع الأرض التي كان يصعد عمله منها إلى السماء تبكي عليه بعد موته. يعني المؤمن."}, "70039": {"num": 70039, "aya": 29, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جُبير -من طريق المنهال بن عمرو- في قوله: {فما بكت عليهم السماء والأرض}، قال: يبكي على المؤمن من الأرض مُصلّاه، ويبكي عليه من السماء مَصْعَد عمله."}, "70040": {"num": 70040, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق أبي يحيى- {فَما بَكَتْ عَلَيْهِمُ السَّماءُ والأَرْضُ}، قال: ما مات مؤمن إلا بكتْ عليه السماء والأرض أربعين صباحًا. فقيل له: تبكي؟! قال: تعجب! وما للأرض لا تبكي على عبدٍ كان يعمُرها بالركوع والسجود، وما للسماء لا تبكي على عبد كان لتسبيحه وتكبيره دويّ كدويّ النّحل!."}, "70043": {"num": 70043, "aya": 29, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء بن أبي رباح -من طريق ابن جُريْج- في قوله تعالى: {فَما بَكَتْ عَلَيْهِمُ السَّماءُ والأَرْضُ}، قال: بكاء السماء حُمرة أطرافها."}, "70046": {"num": 70046, "aya": 29, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {فَما بَكَتْ عَلَيْهِمُ السَّماءُ والأَرْضُ}، قال: هي بقاع المؤمن التي كان يُصَلّي فيها مِن الأرض، تبكي عليه إذا مات، وبقاعه من السماء التي يُرفع فيها عمله."}, "70047": {"num": 70047, "aya": 29, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {فَما بَكَتْ عَلَيْهِمُ السَّماءُ والأَرْضُ}، قال: هم كانوا أهونَ على الله مِن ذلك. قال: وكذلك المؤمن، تبكي عليه بقاعه التي كان يُصَلِّي فيها مِن الأرض، ومصعَد عمله مِن السماء."}, "70049": {"num": 70049, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، قال: يُقال: الأرض تبكي على المؤمن أربعين صباحًا."}, "70051": {"num": 70051, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن مجاهد بن جبر -من طريق منصور- قال: ما من ميت يموت إلا تبكي عليه الأرض أربعين صباحًا."}, "70052": {"num": 70052, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس -من طريق مجاهد-، بمثله."}, "70053": {"num": 70053, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن مجاهد بن جبر -من طريق منصور- قال: كان يقال: الأرض تبكي على المؤمن أربعين صباحًا."}, "70054": {"num": 70054, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن مجاهد بن جبر، قال: إنّ العالم إذا مات بكتْ عليه السماء والأرض أربعين صباحًا."}, "70057": {"num": 70057, "aya": 29, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن إسماعيل السُّدّيّ -من طريق الحكم بن ظهير- قال: لَمّا قُتِل الحسين بن علي بَكَتِ السماء عليه، وبكاؤها حُمرتها."}, "70058": {"num": 70058, "aya": 29, "qail": "عطاء الخراساني", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن عطاء الخُراسانيّ، قال: ما مِن عبدٍ يسجد لله سجدة في بُقعة مِن بقاع الأرض إلا شهدت له يوم القيامة، وبَكتْ عليه يوم يموت."}, "70069": {"num": 70069, "aya": 33, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وآتَيْناهُمْ مِنَ الآياتِ ما فِيهِ بَلاءٌ مُبِينٌ}، قال: أنجاهم مِن عدُوِّهم، وأقطعهم البحر، وظلَّل عليهم الغمام، وأنزل عليهم المنّ والسَّلْوى."}, "70071": {"num": 70071, "aya": 33, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وآتَيْناهُمْ مِنَ الآياتِ ما فِيهِ بَلاءٌ مُبِينٌ}، وقرأ: {ونَبْلُوكُمْ بِالشَّرِّ والخَيْرِ فِتْنَةً وإلَيْنا تُرْجَعُونَ} [الأنبياء: 35]، وقال: بلاء مُبين لِمَن آمن بها وكفر بها، بلوى نبتليهم بها، نُمحِّصهم، بلوى اختبار، نختبرهم بالخير والشر، نختبرهم لننظر فيما أتاهم من الآيات مَن يؤمن بها، وينتفع بها ويضيّعها."}}, "n_athar": {"0": 11, "3": 10, "4": 19, "5": 1, "7": 4, "9": 1, "10": 29, "11": 1, "12": 3, "13": 4, "14": 1, "15": 5, "16": 23, "17": 3, "18": 6, "19": 3, "20": 6, "21": 2, "22": 4, "24": 21, "25": 1, "26": 6, "27": 4, "28": 3, "29": 35, "30": 2, "31": 1, "32": 3, "33": 3, "34": 2, "37": 28, "38": 1, "40": 2, "41": 3, "42": 12, "45": 14, "47": 17, "48": 1, "49": 5, "51": 5, "53": 4, "54": 19, "55": 2, "56": 4, "57": 1, "58": 3, "59": 2}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});